1	"use client";
2	
3	import { useEffect, useRef, useState, useSyncExternalStore } from "react";
4	import { ArrowUp, Mic } from "lucide-react";
5	import { motion, useReducedMotion } from "framer-motion";
6	
7	/**
8	 * The homepage prompt box, on the Create page.
9	 *
10	 * ## Why this is a COPY of components/marketing/PromptHero.tsx, not an import
11	 *
12	 * PromptHero is a marketing component and it carries marketing concerns that
13	 * are wrong — not merely unnecessary — on a page reached only by a signed-in
14	 * customer:
15	 *
16	 *   - it stashes the prompt in sessionStorage and pushes /signup (the auth
17	 *     wall). Here there is nothing to stash and nobody to sign up.
18	 *   - it renders a "get N free credits" rewards pill. The signed-in customer
19	 *     has a real balance, stated honestly below the box by CreditNote.
20	 *   - it probes /api/auth/me to decide whether to offer Enhance. Here the
21	 *     answer is always yes, so the probe is a round trip for nothing.
22	 *   - it links out to /wizard and offers a paperclip reference-image picker;
23	 *     this page opens the wizard IN PLACE and has no reference-image path.
24	 *
25	 * Importing it would mean adding props to another owner's file to switch all
26	 * of that off. So the parts the owner asked to keep — the glass treatment, the
27	 * two-layer rotating glow ring, and the Web Speech voice-to-text — are copied
28	 * verbatim below, comments included.
29	 *
30	 * ## The pair must stay recognisably identical
31	 *
32	 * If you change the glow geometry, the SPIN_SQUARE arithmetic, the composer's
33	 * border/shadow treatment, or the speech plumbing HERE, go and look at
34	 * components/marketing/PromptHero.tsx, and vice versa. They are two copies of
35	 * one design on purpose; they are not allowed to drift into two designs.
36	 * `.glow-clip-a/-b` and `.glow-spin-a/-b` in app/globals.css are genuinely
37	 * shared — that file explains the technique and what was tried and rejected.
38	 */
39	
40	// The rotating gradient inside each glow clip MUST be a square that is
41	// larger than the clip's diagonal, or it stops covering the clip partway
42	// through its own rotation and the ring visibly vanishes and returns on a
43	// loop. (An `inset-[-50%]` made it 2x the clip in BOTH axes — e.g.
44	// 1372x296 for a wide composer. Rotated 90deg that occupies 296x1372: only
45	// 296px wide, far short of the ~686px the clip needs covered. Hence "the
46	// glow keeps disappearing.")
47	//
48	// 200% width + aspectRatio 1 gives a square of side 2*clipWidth, which
49	// always exceeds the diagonal. Centering uses margins rather than a
50	// translate because `transform` is owned by the rotation keyframes and a
51	// transform in the animation would override any translate set here —
52	// percentage margins (all sides, per spec) resolve against the containing
53	// block's WIDTH, so -100% on both axes lands the square's center exactly
54	// on the clip's center.
55	const SPIN_SQUARE: React.CSSProperties = {
56	  position: "absolute",
57	  left: "50%",
58	  top: "50%",
59	  width: "200%",
60	  aspectRatio: "1",
61	  marginLeft: "-100%",
62	  marginTop: "-100%",
63	};
64	
65	// The Web Speech API has no types in TypeScript's DOM lib, so this is a
66	// minimal hand-written shim covering exactly the surface used below —
67	// narrower than the real spec on purpose, so it can't quietly drift into
68	// asserting support for members this component never touches.
69	type SpeechRecognitionAlternativeLike = { readonly transcript: string };
70	type SpeechRecognitionResultLike = {
71	  readonly length: number;
72	  readonly [index: number]: SpeechRecognitionAlternativeLike;
73	};
74	type SpeechRecognitionEventLike = {
75	  readonly results: {
76	    readonly length: number;
77	    readonly [index: number]: SpeechRecognitionResultLike;
78	  };
79	};
80	type SpeechRecognitionLike = {
81	  continuous: boolean;
82	  interimResults: boolean;
83	  lang: string;
84	  start: () => void;
85	  stop: () => void;
86	  onresult: ((e: SpeechRecognitionEventLike) => void) | null;
87	  onend: (() => void) | null;
88	  onerror: (() => void) | null;
89	};
90	type SpeechRecognitionCtor = new () => SpeechRecognitionLike;
91	
92	// Narrowed locally rather than via `declare global`: augmenting Window would
93	// collide with the (differently-shaped) definitions any future TS DOM lib
94	// ships for this API.
95	type SpeechCapableWindow = {
96	  SpeechRecognition?: SpeechRecognitionCtor;
97	  webkitSpeechRecognition?: SpeechRecognitionCtor;
98	};
99	
100	function getSpeechRecognition(): SpeechRecognitionCtor | null {
101	  if (typeof window === "undefined") return null;
102	  const w = window as unknown as SpeechCapableWindow;
103	  return w.SpeechRecognition ?? w.webkitSpeechRecognition ?? null;
104	}
105	
106	// Feature detection is *external* state: it is unknowable while rendering on
107	// the server, and rendering the mic button in the server HTML would be a
108	// hydration mismatch. useSyncExternalStore is the sanctioned way to express
109	// that — getServerSnapshot() feeds both SSR and the hydration render, and
110	// React re-reads getSnapshot() only once hydration has finished. Support
111	// never changes within a page's life, so subscribe is a no-op.
112	const NEVER_CHANGES = () => () => {};
113	const readSpeechSupported = () => getSpeechRecognition() !== null;
114	const speechUnsupportedOnServer = () => false;
115	
116	export function PromptBox({
117	  value,
118	  onChange,
119	  onSubmit,
120	  canSubmit,
121	  children,
122	}: {
123	  value: string;
124	  onChange: (next: string) => void;
125	  onSubmit: () => void;
126	  /** False while the box is empty, or while a build would be refused outright. */
127	  canSubmit: boolean;
128	  /** Rendered inside the box, above the textarea — the template badge and the
129	      attached-logo row. Inside rather than above so the glow still hugs the
130	      one box the customer is looking at. */
131	  children?: React.ReactNode;
132	}) {
133	  const reduced = useReducedMotion();
134	  const [focused, setFocused] = useState(false);
135	  const [listening, setListening] = useState(false);
136	  const speechSupported = useSyncExternalStore(
137	    NEVER_CHANGES,
138	    readSpeechSupported,
139	    speechUnsupportedOnServer,
140	  );
141	  const recognitionRef = useRef<SpeechRecognitionLike | null>(null);
142	  const baseValueRef = useRef("");
143	
144	  function toggleListening() {
145	    const Ctor = getSpeechRecognition();
146	    if (!Ctor) return;
147	
148	    if (listening) {
149	      recognitionRef.current?.stop();
150	      return;
151	    }
152	
153	    const rec = new Ctor();
154	    rec.continuous = true;
155	    rec.interimResults = true;
156	    rec.lang = "en-US";
157	    baseValueRef.current = value ? value.trim() + " " : "";
158	
159	    rec.onresult = (e: SpeechRecognitionEventLike) => {
160	      let transcript = "";
161	      for (let i = 0; i < e.results.length; i++) transcript += e.results[i][0].transcript;
162	      onChange((baseValueRef.current + transcript).trimStart());
163	    };
164	    rec.onend = () => setListening(false);
165	    rec.onerror = () => setListening(false);
166	
167	    recognitionRef.current = rec;
168	    rec.start();
169	    setListening(true);
170	  }
171	
172	  useEffect(() => () => recognitionRef.current?.stop(), []);
173	
174	  return (
175	    // This wrapper is sized to exactly the composer box — the glow layers
176	    // below position with -inset-N relative to IT, so the glow hugs just the
177	    // box and never the heading or the chips around it.
178	    <div className="relative">
179	      {/* The glow — a Gemini-style "chasing light" ring, built with only plain
180	          `transform: rotate()` + `overflow: hidden` clipping: no @property, no
181	          CSS masking (both dropped after they didn't visibly work even in a
182	          fresh, verified non-cached browser). Two layers: a thin bright one
183	          and a soft blurred halo.
184	
185	          The blur lives on the CLIP element, not on the rotating child. That
186	          ordering matters: filters apply AFTER the element (and its
187	          overflow:hidden clipping) is rendered, so the blur softens the clip's
188	          hard outer cutoff and lets the light bleed beyond the clip's bounds —
189	          a real falloff. With the blur on the child instead, the clip's crisp
190	          edge survives and the result reads as a chunky solid border.
191	
192	          Opacity is fixed, not keyed off `focused` — an earlier version dimmed
193	          on blur, which read as "disappearing". The composer's own border
194	          below is the right place for a focus affordance; this ring stays
195	          constant. The entrance fade and the ambient pulse are the
196	          glow-fade-in and glow-pulse keyframes on the outer clipper, so the
197	          global prefers-reduced-motion rule in globals.css already covers
198	          them — nothing here animates outside CSS.
199	
200	          NO NEGATIVE Z-INDEX HERE. `-z-10` drops these layers behind the
201	          nearest opaque background and they are then invisible forever. The
202	          layers sit at the default level and the composer is lifted above them
203	          with z-10, which needs no stacking-context trickery to hold. */}
204	      <div
205	        aria-hidden
206	        className="glow-clip-a pointer-events-none absolute -inset-[3px] overflow-hidden rounded-[1.9rem] blur-[5px]"
207	      >
208	        <div
209	          className="glow-spin-a"
210	          style={{
211	            ...SPIN_SQUARE,
212	            // Stops are pushed into distinct quadrants so the colour visibly
213	            // travels around the box as this rotates — closely-spaced hues
214	            // just blur into one flat pink.
215	            background:
216	              "conic-gradient(#f72570 0deg, #a33dff 90deg, #ff9868 180deg, #ff6b67 270deg, #f72570 360deg)",
217	          }}
218	        />
219	      </div>
220	      <div
221	        aria-hidden
222	        className="glow-clip-b pointer-events-none absolute -inset-[14px] overflow-hidden rounded-[2.4rem] blur-[22px]"
223	      >
224	        <div
225	          className="glow-spin-b"
226	          style={{
227	            ...SPIN_SQUARE,
228	            background:
229	              "conic-gradient(from 180deg, #a33dff 0deg, #f72570 90deg, #ff9868 180deg, #ff6b67 270deg, #a33dff 360deg)",
230	          }}
231	        />
232	      </div>
233	
234	      {/* The glass composer. Opaque enough that the animated ring behind it
235	          reads as a halo around the box, not a wash bleeding through onto the
236	          text — earlier versions were translucent enough that the strong glow
237	          showed straight through onto the placeholder. Still picks up a faint
238	          frosted quality from backdrop-blur, just not at the cost of
239	          legibility. */}
240	      <div
241	        className="relative z-10 overflow-hidden rounded-[1.75rem] bg-white/95 backdrop-blur-2xl backdrop-saturate-150 transition-colors duration-300 dark:bg-neutral-950/95"
242	        style={{
243	          // No focus-driven glow here — the animated ring behind the box is the
244	          // only glow, and a second one on focus fought with it. Focus is still
245	          // signalled (it must be, for keyboard users) but with a quiet border
246	          // shift, plus the textarea's own inside outline below.
247	          border: `1.5px solid ${
248	            focused
249	              ? "color-mix(in srgb, white 45%, var(--accent) 55%)"
250	              : "color-mix(in srgb, white 75%, var(--accent) 25%)"
251	          }`,
252	          boxShadow: "var(--sh-s), inset 0 1px 0 rgba(255,255,255,0.5)",
253	        }}
254	      >
255	        {children}
256	
257	        {/* The placeholder was the only label, and it disappears on the first
258	            keystroke. A visible one would change the design, so this is a
259	            sr-only label tied to the field by id. */}
260	        <label htmlFor="create-prompt-input" className="sr-only">
261	          Describe the website you want to create
262	        </label>
263	        <textarea
264	          id="create-prompt-input"
265	          value={value}
266	          onChange={(e) => onChange(e.target.value)}
267	          onFocus={() => setFocused(true)}
268	          onBlur={() => setFocused(false)}
269	          onKeyDown={(e) => {
270	            // Cmd/Ctrl+Enter builds; plain Enter makes a newline. The homepage
271	            // box sends on plain Enter because what it sends is a one-liner and
272	            // costs nothing. Here Enter starts a build that spends the
273	            // customer's credits, and a brief worth building is several
274	            // paragraphs — so this keeps the portal composer's existing rule
275	            // rather than the marketing one. It is the one deliberate
276	            // behavioural difference between the two boxes.
277	            if (e.key === "Enter" && (e.metaKey || e.ctrlKey) && canSubmit) {
278	              e.preventDefault();
279	              onSubmit();
280	            }
281	          }}
282	          rows={6}
283	          placeholder={
284	            listening ? "Listening…" : "Describe the website you want to create…"
285	          }
286	          // A focus-visible outline is drawn INSIDE (negative offset) because
287	          // the composer clips overflow, so `k-focus`'s outward ring would be
288	          // cut off. Same 2px width and the same brand ring variable, so the
289	          // product still has one focus appearance. Mouse clicks are
290	          // unaffected: focus-visible, not focus.
291	          className="w-full resize-none rounded-[1.6rem] bg-transparent px-6 pb-14 pt-5 text-[15px] leading-relaxed text-neutral-900 outline-none placeholder:text-neutral-500 focus-visible:outline-2 focus-visible:outline-offset-[-3px] focus-visible:outline-[var(--brand-ring)] dark:text-white dark:placeholder:text-neutral-400"
292	        />
293	
294	        {/* Rendered only once the client has confirmed the Web Speech API
295	            exists — see the useSyncExternalStore note above. Absent (not
296	            disabled) everywhere it would not work, which is the honest
297	            treatment for a capability the browser simply does not have. */}
298	        {speechSupported && (
299	          <div className="absolute bottom-3 left-3 flex items-center gap-1">
300	            <button
301	              type="button"
302	              onClick={toggleListening}
303	              aria-label={listening ? "Stop voice input" : "Start voice input"}
304	              className={`k-focus relative flex h-9 w-9 items-center justify-center rounded-full transition-colors ${
305	                listening
306	                  ? "text-white"
307	                  : "text-neutral-500 hover:bg-black/5 hover:text-neutral-900 dark:text-neutral-400 dark:hover:bg-white/10 dark:hover:text-white"
308	              }`}
309	              style={listening ? { background: "var(--brand-gradient)" } : undefined}
310	            >
311	              {/* Skipped under reduced motion — it's a framer-motion (JS)
312	                  animation, so the CSS-only reduced-motion rule in globals.css
313	                  doesn't reach it. The button's solid gradient fill still shows
314	                  that recording is on. */}
315	              {listening && !reduced && (
316	                <motion.span
317	                  aria-hidden
318	                  className="absolute inset-0 rounded-full"
319	                  style={{ background: "var(--brand-gradient)" }}
320	                  animate={{ opacity: [0.5, 0, 0.5], scale: [1, 1.6, 1] }}
321	                  transition={{ duration: 1.4, repeat: Infinity, ease: "easeInOut" }}
322	                />
323	              )}
324	              <Mic size={16} strokeWidth={2} className="relative" />
325	            </button>
326	          </div>
327	        )}
328	
329	        {/* The one brand-gradient fill on this view — the primary action. */}
330	        <motion.button
331	          type="button"
332	          onClick={onSubmit}
333	          disabled={!canSubmit}
334	          aria-label="Build my site"
335	          whileHover={canSubmit ? { scale: 1.06 } : undefined}
336	          whileTap={canSubmit ? { scale: 0.94 } : undefined}
337	          className="k-focus absolute bottom-3 right-3 flex h-9 w-9 items-center justify-center rounded-full text-white shadow-[0_6px_18px_-4px_var(--glow)] transition-opacity disabled:opacity-30"
338	          style={{ background: "var(--brand-gradient)" }}
339	        >
340	          <ArrowUp size={16} strokeWidth={2.5} />
341	        </motion.button>
342	      </div>
343	    </div>
344	  );
345	}
