1	"use client";
2	
3	import Link from "next/link";
4	import { useState } from "react";
5	import { LayoutTemplate, Wand2, X } from "lucide-react";
6	import { Badge } from "@/components/ui/Badge";
7	import { Button } from "@/components/ui/Button";
8	import { getTemplate } from "@/lib/templates";
9	import {
10	  TemplatePickerModal,
11	  type TemplatePickerResult,
12	} from "@/components/templates/TemplatePickerModal";
13	import { InlineWizard, type InlineWizardResult } from "@/components/wizard/InlineWizard";
14	import { PromptBox } from "./PromptBox";
15	
16	export type CreditContext = {
17	  balance: number;
18	  estimate: { low: number; high: number };
19	  cap: { cap: number | null; spent: number; remaining: number | null; reached: boolean };
20	};
21	
22	/**
23	 * A logo handed over by the template picker or the wizard.
24	 *
25	 * `dataUrl` is already a `data:image/png;base64,…` produced by
26	 * components/templates/logo.ts / components/wizard/inline-logo.ts, which both
27	 * exist to satisfy the one gate in app/api/generate/route.ts. It travels to
28	 * that route as the `image` field and reaches the model on attempt 1 — see the
29	 * note in CreateFlow.tsx for why that, and not the brand-kit route, is where a
30	 * logo picked up here can honestly go.
31	 */
32	export type AttachedLogo = { dataUrl: string; bytes: number };
33	
34	/** What a completed helper flow hands back to the page. */
35	export type AssistResult = {
36	  /** Lands in the box, editable. Nothing is ever built without a look at it. */
37	  prompt: string;
38	  logo: AttachedLogo | null;
39	  templateName: string | null;
40	};
41	
42	/** Base64 payload size, minus the `data:image/png;base64,` prefix. */
43	function dataUrlBytes(dataUrl: string): number {
44	  const comma = dataUrl.indexOf(",");
45	  return comma === -1 ? 0 : Math.round((dataUrl.length - comma - 1) * 0.75);
46	}
47	
48	/**
49	 * Make sure the palette a helper flow returned is actually IN the text.
50	 *
51	 * Both flows already write their palette into the prompt they assemble (the
52	 * `- Palette: <id> (#a to #b)` line from lib/wizard.ts and
53	 * components/templates/intake.ts), so in the normal case this changes nothing.
54	 * It exists so that a palette which for any reason did NOT make it into the
55	 * prose is folded in rather than silently dropped — the customer picked those
56	 * colours, and `palette` arriving with nowhere to go would mean it never
57	 * reached the build.
58	 *
59	 * Appended to the composer's own text, not to the request behind the
60	 * customer's back: it is then visible and editable like everything else in the
61	 * box, which is the whole rule for these hand-offs.
62	 */
63	function withPalette(prompt: string, palette: string[] | undefined): string {
64	  if (!palette || palette.length === 0) return prompt;
65	  const lower = prompt.toLowerCase();
66	  if (palette.every((hex) => lower.includes(hex.toLowerCase()))) return prompt;
67	  return `${prompt}\n\nUse these exact colours as the palette: ${palette.join(
68	    ", ",
69	  )}. Make them the dominant colours and derive everything else from those hexes — do not substitute a different palette.`;
70	}
71	
72	export function Composer({
73	  value,
74	  onChange,
75	  logo,
76	  onLogoChange,
77	  onAssist,
78	  onSubmit,
79	  fromTemplate,
80	  credits,
81	  canTopUp,
82	}: {
83	  value: string;
84	  onChange: (v: string) => void;
85	  /** Lifted to the flow so a retry after a refused build keeps the logo the
86	      customer handed over, instead of quietly dropping it. */
87	  logo: AttachedLogo | null;
88	  onLogoChange: (logo: AttachedLogo | null) => void;
89	  onAssist: (result: AssistResult) => void;
90	  onSubmit: () => void;
91	  fromTemplate: string | null;
92	  credits: CreditContext;
93	  /** False when Stripe is not configured — the billing page is still the
94	      credit ledger, but calling the link "Top up" would be a dead end. */
95	  canTopUp: boolean;
96	}) {
97	  // Both helpers open OVER this page rather than navigating to
98	  // /dashboard/templates or /wizard. Leaving the page to fetch a sentence and
99	  // coming back is the thing this replaces; the box the customer was looking
100	  // at stays where it was and simply fills in.
101	  const [pickerOpen, setPickerOpen] = useState(false);
102	  const [wizardOpen, setWizardOpen] = useState(false);
103	
104	  const { balance, estimate, cap } = credits;
105	  const outOfCredits = balance <= 0;
106	  const capReached = cap.reached;
107	  const tight = !outOfCredits && balance < estimate.high;
108	  const capTight = !capReached && cap.remaining !== null && cap.remaining < estimate.high;
109	
110	  const blocked = outOfCredits || capReached;
111	  const ready = value.trim().length > 0 && !blocked;
112	
113	  function acceptTemplate(result: TemplatePickerResult) {
114	    setPickerOpen(false);
115	    onAssist({
116	      prompt: withPalette(result.prompt, result.palette),
117	      logo: result.logoDataUrl
118	        ? { dataUrl: result.logoDataUrl, bytes: dataUrlBytes(result.logoDataUrl) }
119	        : null,
120	      templateName: getTemplate(result.templateId)?.name ?? null,
121	    });
122	  }
123	
124	  function acceptWizard(result: InlineWizardResult) {
125	    setWizardOpen(false);
126	    onAssist({
127	      prompt: withPalette(result.prompt, result.palette),
128	      logo: result.logoDataUrl
129	        ? { dataUrl: result.logoDataUrl, bytes: dataUrlBytes(result.logoDataUrl) }
130	        : null,
