469	        console.error("[kodely] build failed", build.id, error);
470	
471	        // Same as the other failure path: charged zero, recorded honestly.
472	        const spent = sumUsage(attemptUsage);
473	
474	        await db.build.update({
475	          where: { id: build.id },
476	          data: {
477	            status: "FAILED",
478	            endedAt: new Date(),
479	            error: message.slice(0, 1000),
480	            filesWritten,
481	            repairAttempts,
482	            creditsCharged: 0,
483	            ...usageColumns(spent),
484	            costMicros: costMicros(model, spent),
485	            // See the note on the other failure path — a blank model makes a
486	            // failure impossible to attribute.
487	            ...(model ? { model } : {}),
488	          },
489	        });
490	
491	        track(EVENTS.buildFailed, {
492	          userId: user.id,
493	          props: {
494	            buildId: build.id,
495	            projectId: project.id,
496	            kind,
497	            repairAttempts,
498	            reason: "error",
499	          },
500	        });
501	
502	        send({ type: "error", message });
503	      } finally {
504	        try {
505	          controller.close();
506	        } catch {
507	          // already closed by the client disconnect path
508	        }
509	      }
510	    },
511	    cancel() {
512	      // The client disconnected — stop the in-flight Anthropic request
513	      // rather than let it run to completion for a response nobody reads.
514	      abortController.abort();
515	    },
516	  });
517	
518	  return new Response(stream, {
519	    headers: {
520	      "Content-Type": "text/event-stream; charset=utf-8",
521	      "Cache-Control": "no-cache, no-transform",
522	      Connection: "keep-alive",
523	    },
524	  });
525	}
