3	/**
4	 * Logo handling for the template picker.
5	 *
6	 * Same shape and the same hard rule as `app/(portal)/dashboard/new/image.ts`,
7	 * which this is deliberately modelled on rather than importing: that module
8	 * belongs to the composer and re-encodes to JPEG, which is wrong for a logo.
9	 * The rule both files exist to enforce is identical — the output MUST match
10	 * `data:image/(png|jpeg|webp);base64,`, because that regex in
11	 * `app/api/generate/route.ts` is the only gate, and anything else is dropped
12	 * server-side without ever telling the customer their logo was ignored.
13	 *
14	 * WHY PNG FIRST
15	 * A logo is usually flat colour with a transparent background. JPEG has no
16	 * alpha, so re-encoding one to JPEG paints the transparency black — the exact
17	 * failure that makes a header lockup look broken. PNG is tried first and kept
18	 * when it fits; only when it does not does this fall back to JPEG, and then it
19	 * flattens onto white first so the fallback is white-backed rather than
20	 * black-backed.
21	 *
22	 * WHY THE SIZE CAPS ARE THE BRAND KIT'S
23	 * `LOGO_LIMITS` in lib/brand-kit.ts carries the arithmetic: a logo is re-sent
24	 * in the user message of every turn of every build, so its byte size is a
25	 * recurring cost, not a one-off. 160px on the longest edge renders crisply up
26	 * to about 80 CSS px — a header lockup at 2x — and keeps the data URI inside
27	 * 16 KiB. Reusing those constants means this picker cannot quietly disagree
28	 * with the rest of the product about what a logo costs.
29	 */
30	
31	/** Exactly what the generate route will accept as an upload. */
32	const ACCEPTED = ["image/png", "image/jpeg", "image/webp"] as const;
33	
34	/** What the file picker offers. Narrower than `image/*` on purpose — `image/*`
35	    would offer a phone's HEIC, which then fails to decode. */
36	export const LOGO_ACCEPT = ".png,.jpg,.jpeg,.webp,image/png,image/jpeg,image/webp";
37	
38	export type LogoResult =
39	  | { ok: true; dataUrl: string; name: string; bytes: number; format: "PNG" | "JPEG" }
40	  | { ok: false; error: string };
41	
42	const OUTPUT_RE = /^data:image\/(png|jpeg|webp);base64,/;
43	
44	function bytesOf(dataUrl: string): number {
45	  const comma = dataUrl.indexOf(",");
46	  return Math.round((dataUrl.length - comma - 1) * 0.75);
47	}
48	
49	export async function prepareLogo(file: File): Promise<LogoResult> {
50	  if (!(ACCEPTED as readonly string[]).includes(file.type)) {
51	    return {
52	      ok: false,
53	      error:
54	        "That file can't be used as a logo. Kodely accepts PNG, JPEG and WebP images — an SVG, PDF or HEIC will be rejected by the builder, so it is refused here instead of failing silently later.",
55	    };
56	  }
57	
58	  try {
59	    const bitmap = await createImageBitmap(file);
60	    const edge = LOGO_LIMITS.RASTER_MAX_EDGE;
61	    const scale = Math.min(1, edge / Math.max(bitmap.width, bitmap.height));
62	    const w = Math.max(1, Math.round(bitmap.width * scale));
63	    const h = Math.max(1, Math.round(bitmap.height * scale));
64	
65	    const canvas = document.createElement("canvas");
66	    canvas.width = w;
67	    canvas.height = h;
68	    const ctx = canvas.getContext("2d");
69	    if (!ctx) return { ok: false, error: "This browser couldn't read that image." };
70	    ctx.drawImage(bitmap, 0, 0, w, h);
71	
72	    let dataUrl = canvas.toDataURL("image/png");
73	    let format: "PNG" | "JPEG" = "PNG";
74	
75	    if (dataUrl.length > LOGO_LIMITS.RASTER_DATA_URI_MAX) {
76	      // Flatten onto white before the JPEG pass: JPEG has no alpha, and an
77	      // un-flattened transparent logo encodes as black.
78	      ctx.globalCompositeOperation = "destination-over";
79	      ctx.fillStyle = "#ffffff";
80	      ctx.fillRect(0, 0, w, h);
81	      dataUrl = canvas.toDataURL("image/jpeg", 0.86);
82	      format = "JPEG";
83	    }
84	
85	    bitmap.close();
86	
87	    if (!OUTPUT_RE.test(dataUrl)) {
88	      return { ok: false, error: "This browser couldn't re-encode that image." };
89	    }
90	    if (dataUrl.length > LOGO_LIMITS.RASTER_DATA_URI_MAX) {
91	      const kb = Math.round(LOGO_LIMITS.RASTER_DATA_URI_MAX / 1024);
92	      return {
93	        ok: false,
94	        error: `That image is still over ${kb} KB after resizing, which is too detailed to be a logo. A photograph won't work here — try a flat mark, or crop it tighter.`,
95	      };
96	    }
97	
98	    return { ok: true, dataUrl, name: file.name, bytes: bytesOf(dataUrl), format };
99	  } catch {
100	    return { ok: false, error: "That image couldn't be read. Try a different file." };
101	  }
102	}
