const [pickerOpen, setPickerOpen] = useState(false);
const [wizardOpen, setWizardOpen] = useState(false);
const pushToast = useToast();

const { balance, estimate, cap } = credits;

/**
 * The "+" button, a paste, and a drop onto the box all end up here — one
 * path so all three agree on what counts as a valid attachment.
 *
 * Video and PDF are refused HERE, before prepareReferenceImage ever runs,
 * with a message specific to the honest reason: there is no video-frame or
 * PDF-text path anywhere in this pipeline, so an "attached" video or PDF
 * would silently do nothing. prepareReferenceImage's own message (for a
 * rejected but still-an-image type, e.g. HEIC or SVG) is a different,
 * narrower claim — "pick a different image format" — and stays as-is.
 */
async function attachFile(file: File, extraIgnored = 0) {
  if (file.type.startsWith("video/") || file.type === "application/pdf") {
    pushToast({
      tone: "danger",
      message:
        "Only images can be attached — Kodely looks at them for colour and style guidance, but has no way to read a video or PDF.",
    });
    return;
  }

  const replacing = logo !== null;
  const result = await prepareReferenceImage(file);
  if (!result.ok) {
    pushToast({ tone: "danger", message: result.error });
    return;
  }

  onLogoChange({ dataUrl: result.dataUrl, bytes: result.bytes });

  // Only one image ever reaches the build, so the newest attachment always
  // wins — this just makes sure that's said out loud rather than the
  // previous thumbnail quietly vanishing with no explanation.
  const notes: string[] = [];
  if (replacing) notes.push("replaced the image you had attached");
  if (extraIgnored > 0) {
    notes.push(
      `only used one of the ${extraIgnored + 1} files you dropped`,
    );
  }
  pushToast({
    tone: "ok",
    message:
      notes.length > 0
        ? `Image attached — ${notes.join("; ")}.`
        : "Image attached — Kodely will look at it on the first build attempt.",
  });
}

